package com.c016.pushupflappy.game

import android.content.Context
import android.media.AudioAttributes
import android.media.SoundPool
import androidx.annotation.RawRes
import com.c016.pushupflappy.R
import java.io.Closeable

/** Short 8-bit sound effects generated by tools/sound_fx.py. Does nothing when disabled. */
class SoundFx(context: Context, enabled: Boolean) : Closeable {

    enum class Sfx(@RawRes val res: Int) {
        SHOT(R.raw.sfx_shot),
        EXPLODE(R.raw.sfx_explode),
        BIG_EXPLODE(R.raw.sfx_big_explode),
        CAPSULE(R.raw.sfx_capsule),
        POWER_UP(R.raw.sfx_powerup),
        HIT(R.raw.sfx_hit),
        WARNING(R.raw.sfx_warning),
        FLAP(R.raw.sfx_flap),
        POINT(R.raw.sfx_point),
    }

    private val pool: SoundPool? = if (enabled) {
        SoundPool.Builder()
            .setMaxStreams(8)
            .setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_GAME)
                    .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                    .build()
            )
            .build()
    } else {
        null
    }

    // Loading is asynchronous; sounds played before they finish loading are skipped.
    private val ids: Map<Sfx, Int> = pool?.let { p -> Sfx.entries.associateWith { p.load(context, it.res, 1) } } ?: emptyMap()

    fun play(sfx: Sfx, volume: Float = 1f) {
        val id = ids[sfx] ?: return
        pool?.play(id, volume, volume, 1, 0, 1f)
    }

    override fun close() {
        pool?.release()
    }
}
